'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {waitForMailButton,composeClosed}=require('./secureshopMailHeaderFullAppBrowser');
async function qualifyMailReadiness({origin,user,password,root,setModels}){
 const browser=await require('./secureshopAnalyticsBrowserOwner').launchOwnedAnalyticsBrowser(root,'mailreadiness');let page,frame,cdp,expired=false,lost=false,captureError,recovered;const blocked=[],errors=[],posts=[],allSendPosts=[],httpErrors=[];
 const timer=setTimeout(()=>{expired=true;void browser.close().catch(()=>{});},180000);
 try{
  page=await browser.newPage();await page.setViewport({width:1440,height:1100});await require('./fullBackendRenderedSecureShop').configurePage(page,origin,blocked,errors);await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);page.on('request',r=>{if(new URL(r.url()).pathname==='/api/secureshop/email/send'&&r.method()==='POST')allSendPosts.push(JSON.parse(r.postData()));});page.on('response',r=>{if(new URL(r.url()).pathname.startsWith('/api/secureshop/email/')&&r.status()>=400)httpErrors.push({path:new URL(r.url()).pathname,status:r.status(),method:r.request().method()});});
  await page.goto(origin+'/workshop-login');await page.waitForSelector('input[placeholder="Enter your username"]');await page.type('input[placeholder="Enter your username"]',user.username);await page.type('input[placeholder="Enter your password"]',password);await page.click('button[type="submit"]');await page.waitForFunction(()=>location.pathname!=='/workshop-login'&&localStorage.getItem('token'));await page.goto(origin+'/workshop/secureshop');
  const iframe=await page.waitForSelector('iframe[title="SecureShop workshop"]');frame=await iframe.contentFrame();await frame.waitForFunction(()=>window.origin==='null');await frame.waitForFunction(()=>document.querySelector('#ss-login-user')||document.querySelector('a[href="/secureshop/login"]'));if(!await frame.$('#ss-login-user'))await frame.click('a[href="/secureshop/login"]');await frame.waitForSelector('#ss-login-user');await frame.type('#ss-login-user','student_merchant');await frame.type('#ss-login-pw','student123');await frame.click('button[type="submit"]');await frame.waitForSelector('[aria-label="Account menu"]');await frame.waitForSelector('a[href="/secureshop/merchant/inbox"]');await frame.click('a[href="/secureshop/merchant/inbox"]');await frame.waitForSelector('[data-testid="inbox-userid"]');
  const pointer=async e=>{await iframe.evaluate(x=>x.scrollIntoView({block:'start',behavior:'instant'}));await e.evaluate(x=>x.scrollIntoView({block:'center',behavior:'instant'}));await frame.waitForFunction(e=>{const r=e.getBoundingClientRect(),hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return !e.disabled&&(hit===e||e.contains(hit));},{timeout:15000},e);await e.click();};const click=async label=>pointer(await waitForMailButton(frame,label));
  const readiness=()=>frame.evaluate(async()=>{const r=await fetch('/api/secureshop/email/readiness');return {status:r.status,body:await r.json()};});
  const initial=await readiness();assert.equal(initial.status,200);assert.equal(initial.body.readinessMeaning,'transport_and_catalog_admission');assert.equal(initial.body.modelCapabilities.actor.model,'owned-actor');assert.equal(initial.body.modelCapabilities.judge.model,'owned-judge');assert.equal(initial.body.modelCapabilities.actor.status,'available');assert.equal(initial.body.modelCapabilities.judge.status,'available');assert.equal(initial.body.objectiveReadiness.ss_mail_header_construction,true);assert(Object.entries(initial.body.objectiveReadiness).filter(([id])=>id!=='ss_mail_header_construction').every(([,v])=>v===false));
  cdp=await page.createCDPSession();cdp.on('Fetch.requestPaused',async event=>{
   if(new URL(event.request.url).pathname.startsWith('/api/secureshop/email/operations/')){
    try{assert.equal(recovered,undefined);const raw=await cdp.send('Fetch.getResponseBody',{requestId:event.requestId});recovered=decodeRecovery(event,raw,{origin,requestId:posts[0]?.requestId});}catch(error){captureError=error;}finally{await cdp.send('Fetch.continueRequest',{requestId:event.requestId}).catch(error=>{captureError=error;});}return;
   }
   try{assert.equal(lost,false);assert.equal(event.request.method,'POST');assert.equal(event.request.url,origin+'/api/secureshop/email/send');assert.equal(event.responseStatusCode,200);posts.push(JSON.parse(event.request.postData));lost=true;await cdp.send('Fetch.fulfillRequest',{requestId:event.requestId,responseCode:502,responseHeaders:[{name:'content-type',value:'application/json'}],body:Buffer.from(JSON.stringify({ok:false,error:'Controlled response loss'})).toString('base64')});}catch(error){captureError=error;await cdp.send('Fetch.continueRequest',{requestId:event.requestId}).catch(()=>{});}
  });await cdp.send('Fetch.enable',{patterns:[{urlPattern:origin+'/api/secureshop/email/send',requestStage:'Response'},{urlPattern:origin+'/api/secureshop/email/operations/send/*',requestStage:'Response'}]});
  await click('Compose');await frame.waitForSelector('[role="dialog"] input[placeholder="someone@example.com"]',{visible:true});const fields=await frame.$$('[role="dialog"] input');assert.equal(fields.length,3);const address=await fields[1].evaluate(e=>e.value);await fields[0].type(address);await fields[2].type('Availability recovery');await frame.type('[role="dialog"] textarea','Ordinary saved input; no grading effect.');await click('Send');await frame.waitForFunction(()=>document.body.innerText.includes('Send not confirmed'),{timeout:15000});assert.equal(lost,true);if(captureError)throw captureError;await pointer(await frame.waitForSelector('[role="dialog"] button[aria-label="Close"]',{visible:true}));await frame.waitForFunction(composeClosed,{timeout:15000});
  setModels({actor:false,judge:true});await new Promise(resolve=>setTimeout(resolve,15500));await click('Check pending mail');await frame.waitForFunction(()=>document.body.innerText.includes('Message saved to lab mail')&&document.body.innerText.includes('Auto-reply: model currently unavailable.'),{timeout:15000});await page.screenshot({path:path.join(root,'mail-readiness-actor-down-recovered.png'),fullPage:true});
  setModels({actor:true,judge:false});await new Promise(resolve=>setTimeout(resolve,15500));await click('Check saved headers');await frame.waitForFunction(()=>document.body.innerText.includes('Grading: model currently unavailable.')&&document.body.innerText.includes('not eligible for objective credit'),{timeout:15000});await page.screenshot({path:path.join(root,'mail-readiness-judge-down.png'),fullPage:true});const final=await readiness();assert.equal(final.body.ready,true);assert.equal(final.body.objectiveReadiness.ss_mail_header_construction,true);assert.equal(final.body.modelCapabilities.judge.status,'model_missing');if(captureError)throw captureError;assert(recovered);assert.equal(recovered.requestId,posts[0].requestId);assert.equal(posts.length,1);assert.deepEqual(allSendPosts,posts);assert.equal(expired,false);assert.equal(blocked.length,0);assert.deepEqual(errors,[]);assert.deepEqual(httpErrors,[{path:'/api/secureshop/email/send',status:502,method:'POST'}]);
  const result={status:'passed',scope:'Controlled exact-model-list availability, real cold mount and saved ordinary request GET recovery; no inference',initial:initial.body,final:final.body,oneSend:true,recovery:recovered,recoveryWhileActorDown:true,ordinaryHeaderIneligible:true,actualModelCalls:0};fs.writeFileSync(path.join(root,'mail-readiness-browser.json'),JSON.stringify(result,null,2));return result;
 }catch(error){if(page)await page.screenshot({path:path.join(root,'mail-readiness-failure.png'),fullPage:true}).catch(()=>{});fs.writeFileSync(path.join(root,'mail-readiness-failure.json'),JSON.stringify({message:error.message,stack:error.stack,blocked,errors,posts},null,2));throw error;}finally{clearTimeout(timer);if(cdp)await cdp.detach().catch(()=>{});await browser.close();}
}
function decodeRecovery(event,raw,{origin,requestId}){assert.match(requestId||'',/^[a-f0-9-]{36}$/i);assert.equal(event.request.method,'GET');assert.equal(event.request.url,origin+'/api/secureshop/email/operations/send/'+requestId);assert.equal(event.responseStatusCode,200);const bytes=Buffer.from(raw.body,raw.base64Encoded?'base64':'utf8');assert(bytes.length<=16384);const body=JSON.parse(bytes.toString());assert.equal(body.ok,true);assert.equal(body.status,'saved');assert.equal(body.requestId,requestId);assert(Number.isSafeInteger(body.email_id)&&body.email_id>0);return body;}
module.exports={qualifyMailReadiness,decodeRecovery};
